using System;

namespace StdbModule;

public static partial class FrenchQuotes
{
    public static class Voltaire
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Il vaut mieux hasarder de sauver un coupable plutôt que de condamner un innocent.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Il y avait autrefois un grain de sable qui se lamentait d'être un atome ignoré dans le désert ; au bout de quelques années il devint diamant, et il est à présent le plus bel ornement de la couronne du roi des Indes.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Dieu n'a créé les femmes que pour apprivoiser les hommes.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "On disputa un peu sur la multiplicité des langues, et on convint que, sans l’aventure de la tour de Babel, toute la terre aurait parlé français.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Ah ! qu'elles sont funestes. Ce sont les vents qui enflent les voiles du vaisseau : elles le submergent quelquefois ; mais sans elles l'homme ne saurait vivre.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Le mieux est l'ennemi du bien", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Qu’il est dur, [...] de ne commencer à connaître le ciel que lorsqu’on me ravit le droit de le contempler !", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "L'optimisme c'est la rage de soutenir que tout est bien quand on est mal.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Tous les évènements sont enchainés dans le meilleur des mondes possibles : car enfin si vous n'aviez pas été chassé d'un beau château à grands coups de pieds dans le derrière pour l'amour de mademoiselle Cunégonde, si vous n'aviez pas été mis à l'Inquisition, si vous n'aviez pas couru l'Amérique à pied, si vous n'aviez pas donné un bon coup d'épée au baron, si vous n'aviez pas perdu tous vos moutons du bon pays d'Eldorado, vous ne mangeriez pas ici des cédrats confits et des pistaches.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Le fanatique aveugle, et le chrétien sincère\nHont porté trop souvent le même caractère ;\nIls ont même courage, ils ont mêmes désirs.\nLe crime a ses héros ; l'erreur a ses martyrs.\nDu vrai zèle et du faux vains juges que nous sommes !\nSouvent les scélérats ressemblent aux grands hommes.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Si l'homme est créé libre, il doit se gouverner\nSi l'homme a des tyrans, il les doît détrôner.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Dieu ne doit point pâlir des sottises du prêtre.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Un lion mort ne vaut pas\nUn moucheron qui respire.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "L’erreur le conduisit par hasard à la vérité.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Il y a tels esprits qui ont besoin de s’appuyer sur la géométrie, et qui tombent quand ils veulent marcher seuls.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Il n'est pas étonnant qu’en tout pays l'homme se soit rendu le maître de la femme, tout étant fondé sur la force. Il a d'ordinaire beaucoup de supériorité par celle du corps et même de l’esprit. On a vu des femmes très savantes comme il en fut de guerrières; mais il n'y en a jamais eu d'inventrices.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Il n'est permis qu'à un aveugle de douter que les blancs, les nègres, les albinos, les Hottentots, les Lapons, les Chinois, les Amériques ne soient des races entièrement différentes.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "L'écriture est la peinture de la voix.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Ainsi presque tout est imitation. L’idée des ''Lettres persanes'' est prise de celle de ''l’Espion turc''. Le Boiardo a imité le Pulci, l’Arioste a imité le Boiardo. Les esprits les plus originaux empruntent les uns des autres.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Que répondre à un homme qui vous dit qu'il aime mieux obéir à Dieu qu'aux hommes et qui, en conséquence, est sûr de mériter le ciel en vous égorgeant ?", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Le fanatisme est à la superstition ce que le transport est à la fièvre, ce que la rage est à la colère.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "J’aimais l’auteur du livre ''de l’Esprit''. Cet homme valait mieux que tous ses ennemis ensemble ; mais je n’ai jamais approuvé ni les erreurs de son livre, ni les vérités triviales qu’il débite avec emphase. J’ai pris son parti hautement, quand des hommes absurdes l’ont condamné pour ces vérités mêmes.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "La superstition est à la religion ce que l'astrologie est à l'astronomie, la fille très folle d'une mère très sage.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "On peut juger du caractère des hommes par leurs entreprises.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Dans nos siècles de barbarie et d’ignorance, qui suivirent la décadence et le déchirement de l’empire romain, nous reçûmes presque tout des Arabes: astronomie, chimie, médecine, et surtout des remèdes plus doux et plus salutaires que ceux qui avaient été connus des Grecs et des Romains. L’algèbre est de l’invention de ces Arabes; notre arithmétique même nous fut apportée par eux.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Il est triste que souvent pour être bon patriote on soit l'ennemi du reste des hommes. […] Celui qui voudrait que sa patrie ne fût jamais ni plus grande, ni plus petite, ni plus riche, ni plus pauvre, serait le citoyen de l'univers.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Ces mêmes Maures cultivèrent les sciences avec succès, et enseignèrent l’Espagne et l’Italie pendant plus de cinq siècles. Les choses sont bien changées. Le pays de saint Augustin n’est plus qu’un repaire de pirates.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Voilà précisément l’histoire des Juifs : Jéricho et Jérusalem sont Toulouse et Montpellier, et le désert du Sinaï est le pays entre Bordeaux et Bayonne.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Qui est en droit de vous rendre absurde est en droit de vous rendre injuste.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "On ne peut désirer ce qu'on ne connaît pas.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Tous les genres sont bons, hormis le genre ennuyeux.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Si Dieu n'existait pas, il faudrait l'inventer.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Je conviens avec vous que le néant vaut, généralement parlant, beaucoup mieux que la vie, le néant a du bon; consolons nous, nous en tâterons. Il est bien clair que nous serons après notre mort ce que nous étions avant de naître, mais pour les deux ou trois minutes de notre existence, qu'en ferons-nous ? Nous sommes ''de petites roues de la grande machine'', de petits animaux à deux pieds et à deux mains comme les singes, moins agiles qu'eux, aussi comiques, et ayant une ''mesure d'idées'' plus grande. Nous obéissons tous au mouvement général imprimé par la nature, nous ne nous donnons rien, nous recevons tout, ''nous ne sommes pas plus les maîtres de nos idées que de la circulation du sang dans nos veines''. Chaque être, chaque manière d'être obéit nécessairement à la loi générale.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Nous sommes comme la nature nous a pétris, automates pensants faits pour aller un certain temps; ''et puis c'est tout.''", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Je prie l'honnête homme qui fera ''Matière'' de bien prouver que le je ne sais quoi qu'on nomme ''matière'' peut aussi bien penser que le je ne sais quoi qu'on appelle ''esprit''.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Un dictionnaire sans citations est un squelette.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Jamais vingt volumes in-folio ne feront de révolution ; ce sont les petits livres portatifs à trente sous qui sont à craindre. Si l'Évangile avait coûté douze cents sesterces, jamais la religion chrétienne ne se serait établie.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Les beaux esprits se rencontrent.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "J’ai dit qu'on reconnut Mahomet pour un grand homme; rien n’est plus impie, dites-vous. Je vous répondrai que ce n’est pas ma faute si ce petit homme a changé la face d’une partie du monde, s’il a gagné des batailles contre des armées dix fois plus nombreuses que les siennes, s’il a fait trembler l’empire romain, s’il a donné les premiers coups à ce colosse que ses successeurs ont écrasé, et s’il a été législateur de l’Asie, de l’Afrique, et d’une partie de l’Europe.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Nous laisserons, vous et moi, madame, ce monde-ci aussi sot, aussi méchant que nous l'avons trouvé en y arrivant. Mais nous laisserons la France plus gueuse et plus vilipendée.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Tant qu’il y aura des fripons et des imbéciles, il y aura des religions. La nôtre est sans contredit la plus ridicule, la plus absurde, et la plus sanguinaire qui ait jamais infecté le monde.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "[Le Christianisme est] la superstition la plus infâme qui ait jamais abruti les hommes et désolé la terre.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Allez, mes Welches [Français], Dieu vous bénisse! vous êtes la chiasse du genre humain. Vous ne méritez pas d'avoir eu parmi vous de grands hommes qui ont porté votre langue jusqu'à Moscou. C'est bien la peine d'avoir tant d'académies pour devenir barbares! Ma juste indignation, mes anges [le comte et la comtesse d'Argental], est égale à la tendresse respectueuse que j'ai pour vous, et qui fait la consolation de mes vieux jours.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Je crois que nous ne nous entendons pas sur l'article du peuple, que vous croyez digne d'être instruit. J'entends par peuple la populace, qui n'a que ses bras pour vivre. Je doute que cet ordre de citoyens ait jamais le temps ni la capacité de s'instruire; ils mourraient de faim avant de devenir philosophes. Il me paraît essentiel qu'il y ait des gueux ignorants. Si vous faisiez valoir comme moi une terre, et si vous aviez des charrues, vous seriez bien de mon avis. Ce n'est pas le manœuvre qu'il faut instruire, c'est le bon bourgeois, c'est l'habitant des villes […] Quand la populace se mêle de raisonner, tout est perdu.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "À l'égard du peuple, il sera toujours sot et barbare […] Ce sont des bœufs auxquels il faut un joug, un aiguillon et du foin.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Il est à propos que le peuple soit guidé, et non pas qu'il soit instruit; il n'est pas digne de l'être.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Je mourrai bientôt, et ce sera en détestant le pays des singes et des tigres, où la folie de ma mère me fit naître il y a bientôt soixante et treize ans.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Le système de l'égalité m'a toujours paru l'orgueil d'un fou.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Je ne connais guère que Jean-Jacques Rousseau à qui on puisse reprocher ces idées d'égalité et d'indépendance, et toutes ces chimères qui ne sont que ridicules.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Je vous recommande beaucoup de courage et beaucoup de mépris pour le genre humain.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Ceux qui crient contre ce qu'on appelle le luxe ne sont guère que des pauvres de mauvaise humeur.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Il me fallait le roi de Prusse pour maître et le peuple anglais pour concitoyen.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Le mensonge n'est un vice que quand il fait du mal; c'est une très grande vertu, quand il fait du bien. Soyez donc plus vertueux que jamais. Il faut mentir comme un diable, non pas timidement, non pas pour un temps mais hardiment et toujours.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "La politique a sa source dans la perversité plus que dans la grandeur de l'esprit humain.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Les paroles sont aux pensées ce que l'or est aux diamants : il est nécessaire pour les mettre en œuvre, mais il en faut peu.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Si Dieu nous a faits à son image, nous le lui avons bien rendu.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Les femmes sont comme les girouettes : elles se fixent quand elles se rouillent.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "C'est une des superstitions de l'esprit humain d'avoir imaginé que la virginité pouvait être une vertu.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Ce fut toute sa vie sa prétention d'avoir l'existence d'un écrivain gentilhomme, qui vit de son bien, s'amuse, joue la tragédie en société, s'égaie avec ses amis et se moque du monde. Bon nombre de préceptes de vie se rapportent à ce régime de gaieté auquel il dérogea souvent, mais sur lequel aussi il revient trop habituellement pour que ce ne soit pas celui qu'il préfère : ''Ce monde est une guerre ; celui qui rit aux dépens des autres est victorieux. — Il faut toujours s'amuser, rien n'est si sain. — Je me ruine [à bâtir], je le sais bien ; mais je m'amuse. Je joue avec la vie ; voilà la seule chose à quoi elle est bonne''.", Author = "Charles-Augustin Sainte-Beuve" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "''L'Europe me suffit'', disait-il un peu impertinemment, ''je ne me soucie guère du tripot de Paris, attendu que ce tripot est souvent conduit par l'envie, par la cabale, par le mauvais goût et par mille petits intérêts qui s'opposent toujours à l'intérêt commun''. Il croyait sincèrement à la décadence des lettres et il le dit en vingt endroits avec une amère énergie : ''La littérature n'est à présent qu'une espèce de brigandage. S'il y a encore quelques hommes de génie à Paris, ils sont persécutés. Les autres sont des corbeaux qui se disputent quelques plumes de cygne du siècle passé qu'ils ont volées et qu'ils ajustent comme ils peuvent à leurs queues noires''.", Author = "Charles-Augustin Sainte-Beuve" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Le poète lyrique français J.-B. Rousseau avait écrit une Ode à la postérité . Voltaire, trouvant que la valeur de l'œuvre ne justifiait nullement son titre, déclara avec esprit : « Le poème n'arrivera pas à son adresse »", Author = "Sigmund Freud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Ceux qui peuvent vous faire croire à des absurdités peuvent vous faire commettre des atrocités.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Plus les hommes seront éclairés, et plus ils seront libres.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Plus mes compatriotes chercheront la vérité, plus ils aimeront leur liberté. La même force d’esprit qui nous conduit au vrai nous rend bons citoyens. Qu’est-ce en effet que d’être libres ? C’est raisonner juste, c’est connaître les droits de l’homme ; et quand on les connaît bien, on les défend de même.", Author = "Voltaire" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Vous me parlez de ce Voltaire ! Pourquoi le nom de ce baladin souille-t-il vos lettres ? Le malheureux a perdu ma patrie ; je le haïrais davantage si je le méprisais moins. Je ne vois dans ses grands talents qu'un opprobre de plus qui le déshonore par l'indigne usage qu'il en fait. Ses talents ne lui servent, ainsi que ses richesses, qu'à nourrir la dépravation de son cœur […]  Ce fanfaron d'impiété, ce beau génie et cette ame basse, cet homme si grand par ses talents, et si vil par leur usage, nous laissera de longs et cruels souvenirs de son séjour parmi nous. La ruine des mœurs, la perte de la liberté, qui en est la suite inévitable, seront chez nos neveux les monuments de sa gloire et de sa reconnaissance. S'il reste dans leur cour quelque amour pour la patrie, ils détesteront sa mémoire, et il en sera plus souvent maudit qu'admiré.", Author = "J. J. Rousseau" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Voltaire, adroit plagiaire, qui eut l'art d'avoir l'esprit de tous ses devanciers, et qui ne montra d'originalité que dans la finesse de ses\nflagorneries, écrivain scandaleux qui pervertit la jeunesse par les leçons d'une fausse philosophie, et dont le cœur fut le trône de l'envie, de l'avarice, de la malignité, de la vengeance, de la perfidie et de toutes les passions qui dégradent la nature humaine !", Author = "Jean-Paul Marat" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Il est impossible que Voltaire contente, et impossible qu’il ne plaise pas.", Author = "Joseph Joubert" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Voltaire a introduit et mis à la mode un tel luxe, dans les ouvrages de l’esprit, qu’on ne peut plus offrir les mets ordinaires que dans des plats d’or ou d’argent. Tant d’attention à plaire à son lecteur, annonce plus de vanité que de vertu, plus d’envie de séduire que de servir, plus d’ambition que d’autorité, plus d’art que de nature, et tous ces agréments exigent plutôt un grand maître qu’un grand homme.", Author = "Joseph Joubert" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Le génie mérite qu'on le salue, mais il doit souffrir qu'on le juge. Il n'y a d'inviolable au monde que la justice et la vérité. Non, Voltaire n'aima pas assez le peuple. […] sa pitié n'eut jamais rien d'actif et qui vînt d'un sentiment démocratique; c'était une pitié de grand seigneur mêlé de hauteur et de mépris. […] En revanche, on sait jusqu'où il fit descendre, à l'égard des grands, l'humilité de ses hommages ; dans quelles puériles jouissances la faveur des cours retint sa vanité captive, et combien il aimait à se parer du titre de gentilhomme de la chambre. […] Calculées ou sincères , de semblables adulations étaient sans dignité ; et Voltaire ne se serait jamais abaissé jusque-là, s'il avait eu ce généreux orgueil qui se puise dans le sentiment de l'égalité. Mais né d'ailleurs avec une nature souple, il se trouva, dès son entrée dans la vie active, égaré parmi les Vendôme, les Richelieu, les Conti, les La Fare, les Chaulieu ; et dans ce cercle, où l'art du courtisan s'apprenait à l'école du bon goût, il perdit tout ce qui constitue les fiers caractères et les âmes viriles. […] Voltaire n'était pas fait, on le voit, pour chercher dans une révolution politique et sociale le salut du peuple. Changer hardiment, profondément, les conditions matérielles de l'État et de la société, il n'y songeait même pas.", Author = "Louis Blanc" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "M. de Voltaire nous assure qu'il [Mahomet] avait une éloquence vive et forte, des yeux perçants, une physionomie heureuse, l'intrépidité d'Alexandre, la libéralité et la sobriété dont Alexandre aurait eu besoin pour être un grand homme en tout. A la beauté de ce portrait, ne prendrait-on pas Voltaire pour un petit Maimbourg ? Il nous représente Mahomet comme un homme qui a eu la gloire de tirer presque toute l'Asie des ténèbres de l'idôlatrie. Il extrait quelques paroles de divers endroits de l'Alcoran, dont il admire le Sublime. Il trouve que sa loi est extrêmement sage, ques ses lois civiles sont bonnes et que son dogme est admirable en ce qu'il se conforme avec le nôtre. Enfin pour prémunir les lecteurs contre tout ce que les Chrétiens ont dit méchamment de Mahomet, il avertit que ce ne sont guère que des sottises débitées par des moines ignorants et insensés.", Author = "Claude-Adrien Nonnotte" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "L'Empereur […] fait fort peu de cas de Voltaire, plein, dit-il, de boursouflure, de clinquant ; toujours faux, ne connaissant ni les hommes ni les choses, ni la vérité, ni la grandeur des passions.", Author = "Napoléon Bonaparte" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "J'aime le grand Voltaire autant que je déteste le grand Rousseau […] Bref, [Voltaire] me semble ardant, acharné, convaincu, superbe. Son \"Écrasons l'infâme\" me fait l'effet d'un cri de croisade. Tout son intelligence était une machine de guerre. Et ce qui me le fait chérir, c'est le dégoût que m'inspirent les voltairiens, des gens qui rient sur les grandes choses. Est-ce qu'il riait, lui? Il grinçait!", Author = "Gustave Flaubert" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Quand on ne songe qu'à l'idéal de l'agrément, à la fleur de fine raillerie et d'urbanité, on se plaît à se figurer Voltaire dans cette demi-retraite, dans ces jouissances de société qu'il rêva bien souvent, qu'il traversa quelquefois, mais d'où il s'échappait toujours. Il traversa bien souvent dans sa vie de ces cercles délicieux qui se formaient un moment autour de lui, qui se ralliaient à son brillant, dont il était le génie familier et l'âme, et il en sortait bientôt par quelque accident. L'accident au fond venait de lui : il tenait à un défaut et à une qualité. Le défaut, c'était le besoin d'action à tout prix, le besoin de bruit et de renommée qui ne se passait ni des intrigues, ni des manèges, et qui jouait avec les moyens scabreux : de là toute une suite d'indiscrétions, de déguisements, de rétractations, de désaveux, de mensonges, une infinité de misères.", Author = "Charles-Augustin Sainte-Beuve" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "A l'entendre, lui l'homme de la publicité harcelante et qui fatigua la renommée, il ne publiait jamais, presque jamais, ses livres que malgré lui, à son corps défendant : il avait un secrétaire qui le volait, un ami indiscret qui colportait ses manuscrits ; le libraire pirate s'emparait de son bien en le gâtant, en le falsifiant, et force lui était alors d'imprimer lui-même ses productions et de les livrer au public dans leur sincérité.", Author = "Charles-Augustin Sainte-Beuve" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Voltaire", Text = "Voltaire est contre les majorités et les méprises ; en fait de raison, les masses lui paraissent naturellement bêtes ; il ne croit au bon sens que chez un petit nombre et c'est assez pour lui si l'on parvient à grossir peu à peu le petit troupeau.", Author = "Charles-Augustin Sainte-Beuve" },
        };
    }
}